///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name etnChangePage
 * @description etn Change Page 처리
 * @param {*} tab tab
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.etnChangePage = async function (tab) {
    scwin.form = (document.etnListForm || { elements: [] });
    const lastSaveStatCdInt = parseInt($c.util.getComponent('dma_EtnChangePageReq').get('lastSaveStatCd'));
    if (tab === 1) {
        $c.util.getComponent('dma_EtnChangePageReq').set('method', 'viewIsuTab');
    } else {
        if (tab === 2) {
            $c.util.getComponent('dma_EtnChangePageReq').set('method', 'viewIsurTab');
        } else {
            if (tab === 3) {
                return;
            } else {
                $c.util.getComponent('dma_EtnChangePageReq').set('method', 'viewAttachFileTab');
            }
        }
    }
    scwin.form.action = 'EtnList.do';
    await scwin.tx_fn_EtnChangePage();
};

/**
 * @method
 * @name register
 * @description register 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.register = async function () {
    if (!await $c.fil.confirmJob('I')) {
        return;
    }
    scwin.form = (document.etnListForm || { elements: [] });
    $c.util.getComponent('dma_EtnChangePageReq').set('method', 'saveSrtyLpTab');
    scwin.form.action = 'EtnList.do';
    await scwin.tx_fn_Register();
};

/**
 * @method
 * @name etnSub
 * @description etn Sub 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.etnSub = async function () {
    if (!await $c.fil.confirmJob('S')) {
        return;
    }
    scwin.form = (document.etnListForm || { elements: [] });
    scwin.form.action = "EtnList.do";
    $c.util.getComponent('dma_EtnChangePageReq').set('method', 'submitList');
    await scwin.tx_fn_EtnSub();
};

/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function () {
    scwin.form = (document.etnListForm || { elements: [] });
    scwin.form.action = "EtnList.do";
    $c.util.getComponent('dma_EtnChangePageReq').set('listBzTpCd', "");
    $c.util.getComponent('dma_EtnChangePageReq').set('method', 'searchList');
    await scwin.tx_fn_Search();
};

/**
 * @method
 * @name cal
 * @description cal 처리
 * @returns {void}
 * @hidden N
 */
scwin.cal = function () {
    if (($c.util.getComponent('txt_riskAsstVal1').getValue() == null ? '' : String($c.util.getComponent('txt_riskAsstVal1').getValue())) !== '' && $c.util.getComponent('txt_riskAsstVal1').getValue() !== 0) {
        const basEqtycap1Number = scwin.rmComma($c.util.getComponent('txt_basEqtycap1').getValue());
        const riskAsstVal1Number = scwin.rmComma($c.util.getComponent('txt_riskAsstVal1').getValue());
        const etnSrtyPrincCapRto1 = $c.num.formatNumber(String(Math.floor(basEqtycap1Number / riskAsstVal1Number * 10000) / 100));
        etnSrtyPrincCapRto1.setLabel(etnSrtyPrincCapRto1);
    }
    if (($c.util.getComponent('txt_riskAsstVal2').getValue() == null ? '' : String($c.util.getComponent('txt_riskAsstVal2').getValue())) !== '' && $c.util.getComponent('txt_riskAsstVal2').getValue() !== 0) {
        const basEqtycap2Number = scwin.rmComma($c.util.getComponent('txt_basEqtycap2').getValue());
        const riskAsstVal2Number = scwin.rmComma($c.util.getComponent('txt_riskAsstVal2').getValue());
        const etnSrtyPrincCapRto2 = $c.num.formatNumber(String(Math.floor(basEqtycap2Number / riskAsstVal2Number * 10000) / 100));
        etnSrtyPrincCapRto2.setLabel(etnSrtyPrincCapRto2);
    }
    if (($c.util.getComponent('txt_riskAsstVal3').getValue() == null ? '' : String($c.util.getComponent('txt_riskAsstVal3').getValue())) !== '' && $c.util.getComponent('txt_riskAsstVal3').getValue() !== 0) {
        const basEqtycap3Number = scwin.rmComma($c.util.getComponent('txt_basEqtycap3').getValue());
        const riskAsstVal3Number = scwin.rmComma($c.util.getComponent('txt_riskAsstVal3').getValue());
        const etnSrtyPrincCapRto3 = $c.num.formatNumber(String(Math.floor(basEqtycap3Number / riskAsstVal3Number * 10000) / 100));
        etnSrtyPrincCapRto3.setLabel(etnSrtyPrincCapRto3);
    }
    if (($c.util.getComponent('txt_srtyEqtycap').getValue() == null ? '' : String($c.util.getComponent('txt_srtyEqtycap').getValue())) !== '' && $c.util.getComponent('txt_srtyEqtycap').getValue() !== 0) {
        const srtyEqtycapNumber = scwin.rmComma($c.util.getComponent('txt_srtyEqtycap').getValue());
        const srtyIsuTotamtNumber = scwin.rmComma($c.util.getComponent('txt_srtyIsuTotamt').getValue());
        const srtyMiscIsuAmt = scwin.rmComma($c.util.getComponent('txt_srtyMiscIsuAmt').getValue());
        const srtyIsuLimit = $c.num.formatNumber(String(Math.floor((srtyIsuTotamtNumber + srtyMiscIsuAmt) / srtyEqtycapNumber * 10000) / 100));
        srtyIsuLimit.setLabel(srtyIsuLimit);
    }
};

/**
 * @method
 * @name rmComma
 * @description rm Comma 처리
 * @param {String} str str
 * @returns {void}
 * @hidden N
 */
scwin.rmComma = function (str) {

    //    if( str == null || str == "" || str == 0 ) return '';
    //    if( str == null || str == ""  ) return '';
    if( str == null || str === ""  ) return Number(str);   // 2009.07.02 수정. 항목 미입력시 합계 오류발생

    reg =  new RegExp(",","g");

    return Number(str.replace(reg,''));
};
// [A] 초기 목록 미해결 — jldfil70604: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)

// 억제된 trigger 함수의 as-is 이름 별칭 (호출자 정합)
